const api={
  async signInPassword(email,password){const {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;},
  async resetPassword(email){const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;},
  async setPassword(password){const {error}=await sb.auth.updateUser({password});if(error)throw error;},
  async sendLink(email){const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname,shouldCreateUser:true}});if(error)throw error;},
  async load(){
    const uid=S.user.id;
    const [prof,mem,saved,uses,steps]=await Promise.all([
      sb.from("member_profiles").select("*").eq("user_id",uid).maybeSingle(),
      sb.from("members").select("status,current_period_end").eq("user_id",uid).maybeSingle(),
      sb.from("saved_prompts").select("slug"),
      sb.from("prompt_uses").select("slug,hours_saved,created_at").order("created_at",{ascending:false}),
      sb.from("plan_steps").select("*").order("position")]);
    S.profile=prof.data||null;
    const m=mem.data;S.isPro=!!(m&&["active","trialing"].includes(m.status)&&(!m.current_period_end||new Date(m.current_period_end)>new Date()));
    S.saved=new Set((saved.data||[]).map(r=>r.slug));S.uses=uses.data||[];S.steps=steps.data||[];
    if(S.isPro){const b=await sb.from("premium_prompt_bodies").select("slug,prompt");(b.data||[]).forEach(r=>{S.bodies[r.slug]=r.prompt;});}
    try{const ad=await sb.rpc("am_i_admin");S.isAdmin=ad.data===true;}catch(e){S.isAdmin=false;}
    if(S.isAdmin){const [c,ov,ar,ta,tf]=await Promise.all([sb.from("consultation_requests").select("*").order("created_at",{ascending:false}),sb.rpc("admin_overview"),sb.from("article_queue").select("*").order("created_at",{ascending:false}).limit(30),sb.from("tester_applications").select("*").order("created_at",{ascending:false}),sb.from("tester_feedback").select("*").order("created_at",{ascending:false})]);S.consults=c.data||[];S.admin={overview:ov.data||{},articles:ar.data||[],testers:ta.data||[],feedback:(tf.data||[]).filter(x=>x.user_id!==uid)};}
    try{const [pb,it,bo,pu,pr,pj]=await Promise.all([sb.from("playbooks").select("*").order("sort"),sb.from("playbook_items").select("id,playbook_slug,position,module,kind,title,summary,time_saved,tool,is_sample").order("position"),sb.from("playbook_item_bodies").select("item_id,body"),sb.from("playbook_purchases").select("playbook_slug,created_at,source"),sb.from("playbook_progress").select("item_id,done_at"),sb.from("playbook_projects").select("*")]);
      try{const fb=await sb.from("tester_feedback").select("playbook_slug,user_id").eq("user_id",uid);S.myFeedback=fb.data||[];}catch(e){S.myFeedback=[];}
      if(pb.data&&pb.data.length)S.pb={playbooks:pb.data,items:it.data||[],bodies:bo.data||[],purchases:pu.data||[],progress:pr.data||[],projects:pj.data||[]};}catch(e){}
  },
  async updateConsult(r,patch){const {error}=await sb.from("consultation_requests").update(patch).eq("id",r.id);if(error)throw error;Object.assign(r,patch);},
  async saveProfile(p){const row=Object.assign({},p,{user_id:S.user.id,onboarded_at:new Date().toISOString()});const {data,error}=await sb.from("member_profiles").upsert(row).select().single();if(error)throw error;S.profile=data;},
  async replacePlan(steps){await sb.from("plan_steps").delete().eq("user_id",S.user.id);const rows=steps.map(s=>Object.assign({user_id:S.user.id},s));const {data,error}=await sb.from("plan_steps").insert(rows).select();if(error)throw error;S.steps=(data||[]).sort((a,b)=>a.position-b.position);},
  async toggleStep(step){const done_at=step.done_at?null:new Date().toISOString();const {error}=await sb.from("plan_steps").update({done_at}).eq("id",step.id);if(error)throw error;step.done_at=done_at;},
  async toggleSave(slug){if(S.saved.has(slug)){await sb.from("saved_prompts").delete().eq("slug",slug);S.saved.delete(slug);}else{const {error}=await sb.from("saved_prompts").insert({slug});if(error)throw error;S.saved.add(slug);}},
  async logUse(slug,hours){const {data,error}=await sb.from("prompt_uses").insert({slug,hours_saved:hours}).select().single();if(error)throw error;S.uses.unshift(data);},
  async togglePbItem(id){if(S.pb.progress.some(x=>x.item_id===id)){const {error}=await sb.from("playbook_progress").delete().eq("user_id",S.user.id).eq("item_id",id);if(error)throw error;S.pb.progress=S.pb.progress.filter(x=>x.item_id!==id);}else{const row={user_id:S.user.id,item_id:id,done_at:new Date().toISOString()};const {error}=await sb.from("playbook_progress").upsert(row);if(error)throw error;S.pb.progress.push(row);}},
  async saveProject(slug,content,submit){const row={user_id:S.user.id,playbook_slug:slug,content,updated_at:new Date().toISOString()};const ex=pbProject(slug);if(submit)row.submitted_at=new Date().toISOString();else if(ex&&ex.submitted_at)row.submitted_at=ex.submitted_at;
    const {data,error}=await sb.from("playbook_projects").upsert(row,{onConflict:"user_id,playbook_slug"}).select().single();if(error)throw error;S.pb.projects=(S.pb.projects||[]).filter(x=>!(x.playbook_slug===slug&&x.user_id===S.user.id)).concat([data]);},
  async projectFeedback(pr,text){const {error}=await sb.rpc("give_project_feedback",{p_user:pr.user_id,p_slug:pr.playbook_slug,p_feedback:text});if(error)throw error;pr.feedback=text;pr.feedback_at=new Date().toISOString();},
  async acceptTester(a,slug){const {data,error}=await sb.rpc("admin_accept_tester",{p_id:a.id,p_slug:slug});if(error)throw error;Object.assign(a,{status:"accepted",playbook_slug:slug});const o=S.admin.overview;if(o)o.testers_new=S.admin.testers.filter(x=>x.status==="new").length;return data;},
  async updateTester(a,patch){const {error}=await sb.from("tester_applications").update(patch).eq("id",a.id);if(error)throw error;Object.assign(a,patch);const o=S.admin.overview;if(o)o.testers_new=S.admin.testers.filter(x=>x.status==="new").length;},
  async saveFeedback(row){const r=Object.assign({user_id:S.user.id,updated_at:new Date().toISOString()},row);const {error}=await sb.from("tester_feedback").upsert(r,{onConflict:"user_id,playbook_slug"});if(error)throw error;S.myFeedback=(S.myFeedback||[]).concat([{playbook_slug:row.playbook_slug}]);},
  async updateArticle(a,patch){const {error}=await sb.from("article_queue").update(patch).eq("id",a.id);if(error)throw error;Object.assign(a,patch);const o=S.admin.overview;if(o)o.articles_awaiting=S.admin.articles.filter(x=>x.status==="awaiting").length;},
  async signOut(){await sb.auth.signOut();}
};
