/* ---------- Consultations (Jay only): each request turned into a ready-to-use brief ---------- */
const BRIEF_PROMPTS={questions:["salon-dm-replies","website-faq-page"],chasing:["quote-follow-up","clinic-no-show-reminders"],social:["fitness-month-of-posts"],email:["inbox-zero-triage","monday-ceo-hour"],bookings:["clinic-no-show-reminders"],proposals:["consultant-call-to-proposal","trades-voice-note-quote"],finance:["pro-fin-cash-flow-forecast","pro-fin-kpi-dashboard"],hiring:["messy-notes-to-sop","pro-team-onboarding-30-60-90"]};
