  const s=ONB[onbI];$("onb-dots").innerHTML=ONB.map((_,i)=>'<i class="'+(i<=onbI?"on":"")+'"></i>').join("");
  $("onb-count").textContent="Quick setup · "+(onbI+1)+" of "+ONB.length;$("onb-q").textContent=s.q;$("onb-help").textContent=s.help;
  const b=$("onb-body");b.textContent="";
