let authPw=false;
function setAuthMode(pw){authPw=pw;$("auth-pass").hidden=!pw;$("auth-forgot-wrap").hidden=!pw;$("auth-send").textContent=pw?"Sign in":"Email me a sign-in link";$("auth-mode").textContent=pw?"Email me a sign-in link instead":"Sign in with a password instead";$("auth-status").textContent="";if(pw)$("auth-pass").focus();}
