$("auth-forgot").onclick=async()=>{const email=$("auth-email").value.trim(),st=$("auth-status");
  if(!/^\S+@\S+\.\S+$/.test(email)){st.textContent="Type your email address above first.";$("auth-email").focus();return;}
  st.textContent="Sending…";try{await A.resetPassword(email);st.textContent="If there's an account for that email, a link to choose a new password is on its way. Check spam if you can't see it.";}
  catch(err){const msg=String(err&&err.message||"");st.textContent=/seconds|rate limit|too many/i.test(msg)?"I've just sent one. You can ask again in about a minute.":"That didn't go through. Try again in a minute.";}};
$("auth-form").addEventListener("submit",async e=>{e.preventDefault();const email=$("auth-email").value.trim(),st=$("auth-status");
  if(!/^\S+@\S+\.\S+$/.test(email)){st.textContent="Please check your email address and try again.";return;}
  if(authPw){const pw=$("auth-pass").value;if(!pw){st.textContent="Type your password.";$("auth-pass").focus();return;}
    $("auth-send").disabled=true;st.textContent="Signing in…";
    try{await A.signInPassword(email,pw);st.textContent="";$("auth-pass").value="";}
    catch(err){const msg=String(err&&err.message||"");st.textContent=/invalid login|credentials/i.test(msg)?"That email and password don't match. Haven't set a password yet? Use an email link instead, then set one in Account.":/not confirmed/i.test(msg)?"Please confirm your email first using the link we sent you.":/seconds|rate limit|too many/i.test(msg)?"Too many tries. Please wait a minute and try again.":"That didn't go through. Please try again in a minute.";}
    finally{$("auth-send").disabled=false;}return;}
  $("auth-send").disabled=true;st.textContent="Sending…";
  try{await A.sendLink(email);st.textContent="Done. Check your inbox for a link from Jay's AI Playbook. Tap the newest link. It works once and expires after an hour. Can't see it? Have a look in spam.";}
  catch(err){const msg=String(err&&err.message||"");
    st.textContent=/seconds|rate limit|too many/i.test(msg)?"I've just sent you a link, so please check your inbox (and spam) first. You can ask for a new one in about a minute.":"That didn't go through. Please check your connection and try again in a minute.";}
  finally{$("auth-send").disabled=false;}});
